public boolean[] sieve(int n) {
    boolean[] isPrime = new boolean[n + 1];
    Arrays.fill(isPrime, true);
    if (n >= 0) isPrime[0] = false;
    if (n >= 1) isPrime[1] = false;
    for (int p = 2; (long) p * p <= n; p++) {
        if (isPrime[p]) {
            for (int multiple = p * p; multiple <= n; multiple += p) {
                isPrime[multiple] = false;
            }
        }
    }
    return isPrime;
}

public List<Integer> primeFactors(int n) {
    List<Integer> factors = new ArrayList<>();
    for (int p = 2; (long) p * p <= n; p++) {
        while (n % p == 0) {
            factors.add(p);
            n /= p;
        }
    }
    if (n > 1) factors.add(n);
    return factors;
}
public int[] buildSPF(int n) {
    int[] spf = new int[n + 1];
    for (int i = 2; i <= n; i++) {
        if (spf[i] == 0) {
            for (int j = i; j <= n; j += i) {
                if (spf[j] == 0) spf[j] = i;
            }
        }
    }
    return spf;
}

public long fastPow(long base, long exp, long mod) {
    long result = 1;
    base %= mod;
    while (exp > 0) {
        if ((exp & 1) == 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

public int gcd(int a, int b) {
    while (b != 0) {
        int tmp = b;
        b = a % b;
        a = tmp;
    }
    return a;
}
public long lcm(int a, int b) {
    return (long) (a / gcd(a, b)) * b;
}

class Combinatorics {
    private static final int MOD = 1_000_000_007;
    private long[] fact, invFact;
    public Combinatorics(int n) {
        fact = new long[n + 1];
        invFact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[n] = power(fact[n], MOD - 2);
        for (int i = n; i > 0; i--) invFact[i - 1] = invFact[i] * i % MOD;
    }
    public long nCr(int n, int r) {
        if (r < 0 || r > n) return 0;
        return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
    }
    private long power(long base, long exp) {
        long result = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) result = result * base % MOD;
            base = base * base % MOD;
            exp >>= 1;
        }
        return result;
    }
}

public int reverse(int x) {
    int result = 0;
    while (x != 0) {
        int digit = x % 10;
        x /= 10;
        if (result > Integer.MAX_VALUE / 10 || (result == Integer.MAX_VALUE / 10 && digit > 7)) return 0;
        if (result < Integer.MIN_VALUE / 10 || (result == Integer.MIN_VALUE / 10 && digit < -8)) return 0;
        result = result * 10 + digit;
    }
    return result;
}

class ReservoirSampler {
    private Random rand = new Random();
    public int[] sample(Iterator<Integer> stream, int k) {
        int[] reservoir = new int[k];
        int i = 0;
        while (stream.hasNext() && i < k) {
            reservoir[i++] = stream.next();
        }
        while (stream.hasNext()) {
            int val = stream.next();
            int j = rand.nextInt(++i);
            if (j < k) reservoir[j] = val;
        }
        return reservoir;
    }
}

public int closestSubsequenceSum(int[] nums, int goal) {
    int n = nums.length, half = n / 2;
    long[] left = subsetSums(nums, 0, half);
    long[] right = subsetSums(nums, half, n);
    Arrays.sort(right);
    long best = Long.MAX_VALUE;
    for (long l : left) {
        long need = goal - l;
        int idx = lowerBound(right, need);
        if (idx < right.length) best = Math.min(best, Math.abs(l + right[idx] - goal));
        if (idx > 0) best = Math.min(best, Math.abs(l + right[idx - 1] - goal));
    }
    return (int) best;
}
private long[] subsetSums(int[] nums, int start, int end) {
    int len = end - start;
    long[] sums = new long[1 << len];
    for (int mask = 0; mask < (1 << len); mask++) {
        long sum = 0;
        for (int i = 0; i < len; i++) {
            if ((mask & (1 << i)) != 0) sum += nums[start + i];
        }
        sums[mask] = sum;
    }
    return sums;
}
private int lowerBound(long[] arr, long target) {
    int lo = 0, hi = arr.length;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (arr[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

public int maxPoints(int[][] points) {
    int n = points.length;
    if (n <= 2) return n;
    int best = 2;
    for (int i = 0; i < n; i++) {
        Map<String, Integer> slopes = new HashMap<>();
        for (int j = i + 1; j < n; j++) {
            int dy = points[j][1] - points[i][1];
            int dx = points[j][0] - points[i][0];
            int g = gcd(Math.abs(dy), Math.abs(dx));
            if (g != 0) { dy /= g; dx /= g; }
            if (dx < 0) { dx = -dx; dy = -dy; }
            String key = dy + "/" + dx;
            slopes.merge(key, 1, Integer::sum);
            best = Math.max(best, slopes.get(key) + 1);
        }
    }
    return best;
}
private int gcd(int a, int b) {
    return b == 0 ? a : gcd(b, a % b);
}

public int myAtoi(String s) {
    int i = 0, n = s.length(), sign = 1;
    while (i < n && s.charAt(i) == ' ') i++;
    if (i < n && (s.charAt(i) == '+' || s.charAt(i) == '-')) {
        sign = s.charAt(i) == '-' ? -1 : 1;
        i++;
    }
    int result = 0;
    while (i < n && Character.isDigit(s.charAt(i))) {
        int digit = s.charAt(i) - '0';
        if (result > (Integer.MAX_VALUE - digit) / 10) {
            return sign == 1 ? Integer.MAX_VALUE : Integer.MIN_VALUE;
        }
        result = result * 10 + digit;
        i++;
    }
    return result * sign;
}
